import inspect, warnings

class Ctx: pass

def get_ctx(): return Ctx()

def remove_ctx(f):
    def wrapper(self, *args, **kwargs):
        if args and isinstance(args[0], Ctx):
            args = args[1:]
        return f(self, *args, **kwargs)
    return wrapper

def add_ctx(f):
    def wrapper(self, *args, **kwargs):
        if not args:
            args = (get_ctx(),)
        elif not isinstance(args[0], Ctx):
            args = (get_ctx(), *args)
        return f(self, *args, **kwargs)
    return wrapper

class Base:
    def handle_exception(self, ctx, e):
        return ("base", e)

def init_subclass(cls):
    method = cls.handle_exception
    base_method = Base.handle_exception
    if method is base_method:
        return None
    iter_params = iter(inspect.signature(method).parameters.values())
    next(iter_params)
    param = next(iter_params, None)
    if param is None or not (
        (param.annotation is inspect.Parameter.empty and param.name == "ctx")
        or (isinstance(param.annotation, str) and param.annotation.rpartition(".")[2] == "AppContext")
        or (inspect.isclass(param.annotation) and issubclass(param.annotation, Ctx))
    ):
        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            warnings.warn(f"'handle_exception' now takes 'ctx'", DeprecationWarning, stacklevel=2)
            print(f"WARNING emitted for class {cls.__name__}: {w[0].message}")
        setattr(cls, "handle_exception", remove_ctx(method))
        setattr(Base, "handle_exception", add_ctx(base_method))

# Old-signature subclass
class OldSigSub(Base):
    def handle_exception(self, e):
        return ("old-sub", e)

init_subclass(OldSigSub)

# Innocent subclass that overrides NOTHING
class ChildOfOld(OldSigSub):
    pass

init_subclass(ChildOfOld)

# Another innocent subclass
class GrandChild(ChildOfOld):
    pass

init_subclass(GrandChild)

# Dispatch simulation through a ChildOfOld instance
inst = ChildOfOld()
print("dispatch result:", inst.handle_exception(get_ctx(), "boom"))

# Grandchild calling super() chain with old signature
class GrandChild2(ChildOfOld):
    def handle_exception(self, e):
        return ("grand2", super().handle_exception(e))

init_subclass(GrandChild2)
g2 = GrandChild2()
print("grand2 result:", g2.handle_exception(get_ctx(), "boom"))

